1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResults = {
19	  results: unknown[];
20	};
21	
22	const PROCESSING_FEE = 5;
23	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
24	const CURSE_SURCHARGE = 0.5;
25	
26	const BASE_PREMIUMS: Record<string, number> = {
27	  sword: 100,
28	  amulet: 60,
29	  staff: 80,
30	  potion: 40,
31	  rune: 25,
32	  moonstone: 25,
33	};
34	
35	const BLOCK_SIZE = 3;
36	const BLOCK_BASE_PREMIUM = 60;
37	
38	const COMPONENT_TYPES = ["rune", "moonstone"];
39	
40	/** Items are priced per type, because the component block applies to alike items. */
41	const groupByType = (items: Item[]): Map<string, Item[]> =>
42	  items.reduce(
43	    (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
44	    new Map<string, Item[]>(),
45	  );
46	
47	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
48	
49	/** Cursed items add a risk surcharge on top of their own base premium. */
50	const itemSurcharges = (item: Item): number =>
51	  item.cursed ? itemBasePremium(item) * CURSE_SURCHARGE : 0;
52	
53	/**
54	 * A building block of exactly 3 alike components is offered at a special base
55	 * premium. "Alike" means the same type, and the block does not repeat: 4 or 7
56	 * runes are charged per item.
57	 */
58	const formsComponentBlock = (type: string, items: Item[]): boolean =>
59	  COMPONENT_TYPES.includes(type) && items.length === BLOCK_SIZE;
60	
61	const alikeItemsBasePremium = (type: string, items: Item[]): number =>
62	  formsComponentBlock(type, items)
63	    ? BLOCK_BASE_PREMIUM
64	    : items.reduce((sum, item) => sum + itemBasePremium(item), 0);
65	
66	const policyBasePremium = (items: Item[]): number =>
67	  [...groupByType(items)].reduce(
68	    (sum, [type, alikeItems]) => sum + alikeItemsBasePremium(type, alikeItems),
69	    0,
70	  );
71	
72	/** Premiums are rounded in the MHPCO's favour, i.e. up. */
73	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
74	
75	/**
76	 * Applies a surcharge additively rather than as `amount * (1 + rate)`.
77	 * The multiplicative form introduces IEEE-754 error that `roundInMHPCOsFavour`
78	 * then amplifies to a whole Gold piece — e.g. `100 * 1.1` is 110.00000000000001,
79	 * which rounds up to 116 instead of the specified 115. Do not "simplify" this.
80	 */
81	const withSurcharge = (amount: number, rate: number): number => amount + amount * rate;
82	
83	const policyItemSurcharges = (items: Item[]): number =>
84	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
85	
86	const quote = (step: QuoteStep): { premium: number } => {
87	  const assessedPremium = withSurcharge(
88	    policyBasePremium(step.items),
89	    INITIAL_ASSESSMENT_SURCHARGE,
90	  );
91	
92	  return {
93	    premium: roundInMHPCOsFavour(
94	      assessedPremium + policyItemSurcharges(step.items) + PROCESSING_FEE,
95	    ),
96	  };
97	};
98	
99	export const runScenario = (scenario: Scenario): ScenarioResults => ({
100	  results: scenario.steps.map(quote),
101	});
